import requests, sys, uuid, time

BASE = "{{TESTVDB_DB_URL}}"
HEADERS = {"Content-Type": "application/json", "Accept": "application/json", "Authorization": "{{TESTVDB_AUTH_HEADER}}"}

coll_name = "TestColl_typeconf_null_" + uuid.uuid4().hex[:8]

# Test 1: params.enableDynamicField = null
payload = {
    "collectionName": coll_name,
    "schema": {
        "autoID": False,
        "enableDynamicField": True,
        "fields": [
            {"fieldName": "id", "dataType": "Int64", "isPrimary": True},
            {"fieldName": "vector", "dataType": "FloatVector", "elementTypeParams": {"dim": 4}}
        ]
    },
    "params": {
        "enableDynamicField": None
    },
    "indexParams": [
        {"fieldName": "vector", "metricType": "COSINE", "indexType": "AUTOINDEX"}
    ]
}

r = requests.post(f"{BASE}/v2/vectordb/collections/create", json=payload, headers=HEADERS)
print(f"Response status: {r.status_code}, body: {r.text}")

# Server should reject params.enableDynamicField=null
if r.status_code == 200 and r.json().get('code') == 0:
    print("[DEFECT: ILLEGAL_SUCCESS] Server accepted params.enableDynamicField=null on collection create!")
    # Cleanup
    requests.post(f"{BASE}/v2/vectordb/collections/drop", json={"collectionName": coll_name}, headers=HEADERS)
    sys.exit(1)
else:
    print(f"OK: Server properly rejected params.enableDynamicField=null (code={r.json().get('code')}, msg={r.json().get('message', r.json().get('msg',''))})")
    sys.exit(0)

